{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "In migraine patients, oral ergotamine—the closest high-similarity ergopeptine analogue—had absolute oral bioavailability of only 0.9–3.4%, directly supporting low F for the query's ergopeptine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ergotamine tartrate oral F was <1% versus IV in patients, confirming that the intact ergopeptine cyclol system is associated with very poor systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Methysergide, a related ergoline, had systemic availability of 13%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Lisuride, another ergoline dopamine agonist, showed 10% oral bioavailability in humans, supporting low F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bromerguride, a brominated ergoline urea, had 29% oral bioavailability, above threshold, but it lacks the peptide cyclol and is less transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Methylergometrine, a simple ergoline amide, had 74% absolute oral bioavailability, showing high F is possible in less complex ergolines; low transferability to the peptide cyclol query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a brominated ergopeptine (bromocriptine-like). The closest high-similarity analogue, ergotamine, shares the intact ergopeptine cyclol scaffold and has human absolute oral F of <1–5%, strongly supporting low bioavailability. Higher-F simple ergolines (bromerguride, methylergometrine) lack the peptide cyclol and are less transferable, so the prediction is low (F <20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule (bromocriptine) was supplied; the closest direct analogue is ergotamine.",
    "The contribution of the peptide cyclol moiety to low oral F is inferred from ergotamine and structural comparison, not directly measured for the query.",
    "Human absolute F data for bromocriptine itself would reduce residual uncertainty."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C21"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "ergotamine/ergopeptine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C01"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "bromerguride/bromoergoline urea"
    },
    {
      "applicability": "low",
      "card_ids": ["C07"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "simple ergoline amides"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "other ergolines (methysergide/lisuride)"
    },
    {
      "applicability": "not_applicable",
      "card_ids": ["C27"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "non-ergoline drugs"
    }
  ],
  "revision_action": "initial"
}

